import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline


_cpp_src = r"""
#include <torch/extension.h>
torch::Tensor max_reduce_forward(torch::Tensor x, int64_t dim);
"""

_cuda_src = r"""
#include <torch/extension.h>
#include <ATen/cuda/CUDAContext.h>
#include <c10/cuda/CUDAGuard.h>
#include <cuda_runtime.h>
#include <float.h>
#include <vector>

__global__ void max_reduce_dim_kernel(
    const float* __restrict__ x,
    float* __restrict__ out,
    long long outer,
    long long reduce,
    long long inner,
    long long total_out)
{
    const long long tid = (long long)blockIdx.x * blockDim.x + threadIdx.x;
    const long long step = (long long)gridDim.x * blockDim.x;
    for (long long out_idx = tid; out_idx < total_out; out_idx += step) {
        long long o = out_idx / inner;
        long long i = out_idx - o * inner;
        long long base = o * reduce * inner + i;
        float m = -FLT_MAX;
        for (long long r = 0; r < reduce; ++r) {
            m = fmaxf(m, __ldg(x + base + r * inner));
        }
        out[out_idx] = m;
    }
}
static long long max_reduce_wave_blocks(int threads) {
    int device = 0;
    C10_CUDA_CHECK(cudaGetDevice(&device));
    int sm_count = 0;
    C10_CUDA_CHECK(cudaDeviceGetAttribute(&sm_count, cudaDevAttrMultiProcessorCount, device));
    int blocks_per_sm = 0;
    C10_CUDA_CHECK(cudaOccupancyMaxActiveBlocksPerMultiprocessor(
        &blocks_per_sm, (const void*)max_reduce_dim_kernel, threads, 0));
    if (blocks_per_sm < 1) blocks_per_sm = 1;
    if (sm_count < 1) sm_count = 1;
    return (long long)sm_count * (long long)blocks_per_sm;
}
torch::Tensor max_reduce_forward(torch::Tensor x, int64_t dim) {
    TORCH_CHECK(x.is_cuda(), "x must be CUDA");
    TORCH_CHECK(x.scalar_type() == at::kFloat, "only float32 is supported");
    const at::cuda::OptionalCUDAGuard guard(x.device());
    auto y = x.contiguous();
    int64_t ndim = y.dim();
    TORCH_CHECK(ndim >= 1, "x must have at least one dimension");
    if (dim < 0) dim += ndim;
    TORCH_CHECK(dim >= 0 && dim < ndim, "dim out of range");
    auto sizes = y.sizes().vec();
    TORCH_CHECK(sizes[dim] > 0, "cannot reduce over an empty dimension");
    long long outer = 1;
    for (int64_t d = 0; d < dim; ++d) outer *= sizes[d];
    long long reduce = sizes[dim];
    long long inner = 1;
    for (int64_t d = dim + 1; d < ndim; ++d) inner *= sizes[d];
    std::vector<int64_t> out_sizes = sizes;
    out_sizes.erase(out_sizes.begin() + dim);
    auto out = at::empty(out_sizes, y.options());
    long long total_out = outer * inner;
    if (total_out == 0) return out;
    const int threads = 256;
    long long total_threads = total_out;
    long long blocks_ll = (total_threads + threads - 1) / threads;
    const long long wave_blocks = max_reduce_wave_blocks(threads);
    if (blocks_ll > wave_blocks) blocks_ll = wave_blocks;
    if (blocks_ll < 1) blocks_ll = 1;
    dim3 blocks((unsigned int)blocks_ll);

    auto stream = at::cuda::getCurrentCUDAStream();
    max_reduce_dim_kernel<<<blocks, threads, 0, stream>>>(
        y.data_ptr<float>(),
        out.data_ptr<float>(),
        outer,
        reduce,
        inner,
        total_out
    );
    C10_CUDA_KERNEL_LAUNCH_CHECK();
    return out;
}
"""

_ext = load_inline(
    name="max_reduce_dim_ext",
    cpp_sources=_cpp_src,
    cuda_sources=_cuda_src,
    functions=["max_reduce_forward"],
    verbose=False,
)


class Model(nn.Module):
    def __init__(self, dim: int):
        super(Model, self).__init__()
        self.dim = dim

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return torch.max(x, dim=self.dim)[0]


class ModelNew(nn.Module):
    def __init__(self, dim: int):
        super(ModelNew, self).__init__()
        self.dim = dim

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        if x.is_cuda and x.dtype == torch.float32:
            return _ext.max_reduce_forward(x, self.dim)
        return torch.max(x, dim=self.dim)[0]

